,iBAHU,CAMZ,gCACE,WAAY,CACZ,0BAA8B,CAC9B,iBAAkB,CAClB,iBAAkB,CAClB,YAAa,CACb,6BAA8B,CAC9B,kBAPa,CAUf,yCACE,YAAa,CACb,sBAAuB,CACvB,cAAe,CACf,OAAQ,CACR,MAAO,CACP,WAAY,CACZ,iBAPsB,CAUxB,yCACE,oBADsB,CAIxB,oCACE,eAAgB,CAChB,kBAAmB,CACnB,eAAgB,CAChB,iBAAkB,CAClB,aAAc,CACd,cANiB,CASnB,4CACE,mCAAoC,CACpC,8BAFyB,CAK3B,iCACE,WADc,CAKhB,2BACE,eAAgB,CAChB,gBAFQ,CAKV,0BACE,WADO,CAIT,iCACE,SAAU,CACV,8BAFc,CC5HhB,+BACE,kBACD,CACD,gCACE,YAAc,CACd,QAAU,CACV,cACD,CACD,uCACE,MAAQ,CACR,WAAa,CACb,kDAAqD,CACrD,sBAAwB,CACxB,aAAe,CACf,cACD,CACD,8CACE,kBAAoB,CACpB,oBACD,CAED,uCACE,YAAc,CACd,qBAAuB,CACvB,sBAAwB,CACxB,OACD,CACD,+BACE,UAAY,CACZ,cACD,CAED,iCACE,eAAiB,CACjB,0CAA+C,CAC/C,gBACD,CAED,oCACE,YACD,CAED,yBACE,oCACE,cAAgB,CAChB,aACD,CACF","sourcesContent":[null,"@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;500;700&display=swap');\n.ark-global-statusbar {\n  font-family: 'Helvetica Neue', Helvetica, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', Arial, sans-serif !important;\n  font-size: var(--ui-font-size, 14px);\n  width: var(--ui-width, 400px);\n}\n.ark-startup-container, .ark-startup-container .main-container {\n  font-family: 'Noto Serif SC', 'PingFang SC', 'Microsoft YaHei', serif !important;\n  font-size: var(--ui-font-size, 14px);\n}\n@media (max-width: 768px) {\n  .ark-global-statusbar {\n    font-size: calc(var(--ui-font-size, 14px) - 2px) !important;\n  }\n  .ark-startup-container, .ark-startup-container .main-container {\n    font-size: calc(var(--ui-font-size, 14px) - 2px) !important;\n  }\n}\n.switch {\n  position: relative;\n  display: inline-block;\n  width: 40px;\n  height: 20px;\n}\n.switch input {\n  opacity: 0;\n  width: 0;\n  height: 0;\n}\n.slider {\n  position: absolute;\n  cursor: pointer;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background-color: #ccc;\n  transition: 0.4s;\n}\n.slider:before {\n  position: absolute;\n  content: '';\n  height: 16px;\n  width: 16px;\n  left: 2px;\n  bottom: 2px;\n  background-color: white;\n  transition: 0.4s;\n}\ninput:checked + .slider {\n  background-color: #007bff;\n}\ninput:checked + .slider:before {\n  transform: translateX(20px);\n}\n.slider.round {\n  border-radius: 20px;\n}\n.slider.round:before {\n  border-radius: 50%;\n}\n.btn-primary, .btn-danger, .btn-success, .btn-warning {\n  flex: 1;\n  padding: 10px;\n  border: none;\n  border-radius: 4px;\n  cursor: pointer;\n  font-weight: bold;\n  color: white;\n}\n.btn-primary {\n  background: #007bff;\n}\n.btn-primary:hover {\n  background: #0056b3;\n}\n.btn-danger {\n  background: #dc3545;\n}\n.btn-danger:hover {\n  background: #a71d2a;\n}\n.btn-success {\n  background: #28a745;\n}\n.btn-success:hover {\n  background: #218838;\n}\n.btn-warning {\n  background: #ff9800;\n}\n.btn-warning:hover {\n  background: #e68a00;\n}\n.wb-actions {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n  margin-bottom: 20px;\n}\n.ark-btn {\n  position: relative;\n  height: 48px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  border: 1px solid var(--ui-border-primary);\n  background: var(--ui-bg);\n  transition: all 0.2s ease;\n  overflow: hidden;\n}\n.ark-btn .btn-content {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  z-index: 2;\n  transition: all 0.2s;\n}\n.ark-btn .btn-text {\n  font-weight: bold;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n  font-size: 0.9em;\n}\n.ark-btn.warning {\n  border-color: #ff9800;\n  color: #ff9800;\n}\n.ark-btn.warning:hover {\n  background: #ff9800;\n  color: #fff;\n}\n.ark-btn.danger {\n  border-color: #f44336;\n  color: #f44336;\n}\n.ark-btn.danger:hover {\n  background: #f44336;\n  color: #fff;\n}\n.ark-btn::after {\n  content: '';\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 0;\n  height: 0;\n  border-style: solid;\n  border-width: 0 10px 10px 0;\n  border-color: transparent currentColor transparent transparent;\n  opacity: 0.5;\n}\n.ark-btn:active {\n  transform: scale(0.98);\n}\n","/* ----------------------------------------------------------------------------\n * Level 2: Shared UI Components (共用组件库)\n * 此文件提取了两大顶层应用中高度重合的结构样式。\n * 它们可以直接挂载在顶层组件的 `<style>`（非 scoped）中，或被子页面按需导入。\n * 注意：由于 theme.scss 已经提取了基础按钮和 Switch 开关，此处仅保留布局类组件\n * ------------------------------------------------------------------------- */\n\n/* --- General Layout & Utility --- */\n.empty-state {\n  text-align: center;\n  padding: 20px;\n  opacity: 0.7;\n}\n\n.hint {\n  font-size: 0.85em;\n  opacity: 0.8;\n  margin-top: 5px;\n}\n\n.warning-box {\n  background: rgba(255, 165, 0, 0.2);\n  border-left: 4px solid orange;\n  padding: 10px;\n  margin-bottom: 15px;\n}\n\n.action-bar {\n  display: flex;\n  gap: 10px;\n}\n\n.action-bar.compact {\n  gap: 5px;\n}\n\n/* --- Global Action Buttons --- */\n.icon-btn {\n  background: transparent;\n  border: none;\n  color: inherit;\n  font-size: 1.1em;\n  cursor: pointer;\n  padding: 0 5px;\n}\n\n.icon-btn.tiny {\n  font-size: 0.9em;\n  padding: 2px 4px;\n  border: 1px solid transparent;\n  border-radius: 4px;\n  cursor: pointer;\n  background: transparent;\n  margin-right: 5px;\n}\n\n.icon-btn.tiny:hover {\n  background: rgba(255, 255, 255, 0.1);\n}\n\n.btn-tiny {\n  font-size: 0.75em;\n  padding: 4px 8px;\n  border: none;\n  border-radius: 4px;\n  cursor: pointer;\n  color: white;\n}\n\n/* --- Common List & Item Structures --- */\n.entry-list {\n  list-style: none;\n  padding: 0;\n  margin: 0 0 15px 0;\n}\n\n.entry-list li {\n  padding: 8px;\n  background: rgba(0, 0, 0, 0.2);\n  margin-bottom: 5px;\n  border-radius: 4px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.entry-list .entry-info {\n  display: flex;\n  align-items: flex-start;\n  flex-wrap: wrap;\n  gap: 8px;\n  flex: 1;\n  min-width: 0;\n  margin-right: 10px;\n}\n\n.entry-list .entry-name {\n  word-break: break-all;\n}\n\n.entry-list .badge {\n  font-size: 0.8em;\n  background: #007bff;\n  padding: 2px 6px;\n  border-radius: 4px;\n  flex-shrink: 0;\n  margin-top: 2px;\n}\n\n.entry-list .badge.blocked {\n  background: var(--ui-border-primary);\n  color: var(--ui-text-secondary);\n}\n\n.disabled-entry {\n  opacity: 0.4;\n}\n\n/* --- Global Icons --- */\n.pin-icon {\n  font-size: 0.9em;\n  margin-right: 4px;\n}\n\n.pin-btn {\n  opacity: 0.5;\n}\n\n.pin-btn.pinned {\n  opacity: 1;\n  background: rgba(255, 165, 0, 0.2);\n}\n","\n@import '../../styles/theme.scss';\n@import '../../styles/shared_ui.scss';\n\n.setting-item {\n  margin-bottom: 15px;\n}\n.theme-buttons {\n  display: flex;\n  gap: 10px;\n  margin-top: 5px;\n}\n.theme-buttons button {\n  flex: 1;\n  padding: 8px;\n  border: 1px solid var(--SmartThemeBorderColor, #444);\n  background: transparent;\n  color: inherit;\n  cursor: pointer;\n}\n.theme-buttons button.active {\n  background: #007bff;\n  border-color: #007bff;\n}\n\n.flex-col-align-start {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 8px;\n}\n.slider-input {\n  width: 100%;\n  cursor: pointer;\n}\n\n.setting-action {\n  margin-top: 25px;\n  border-top: 1px solid rgba(255, 255, 255, 0.1);\n  padding-top: 15px;\n}\n\n.mobile-scale-hint {\n  display: none;\n}\n\n@media (max-width: 768px) {\n  .mobile-scale-hint {\n    display: inline;\n    color: #ff9800;\n  }\n}\n"],"sourceRoot":""}]);
